inputB = list(map(int, sys.stdin.readline().strip().split()))

inputA2 = inputA.copy()
inputB2 = inputB.copy()

def getWonMaxFast(a, b):
    wins = [0, 0, 0]
    for i in range(3):
        good = (i + 1) % 3
        w = min(a[i], b[good])
        wins[i] = w
        a[i] -= w
        b[good] -= w
    return sum(wins)

def getLostMaxFast(a, b):
    ways = [(0,2), (1,0), (2,1), (0,0), (1,1), (2,2)]
    max_lost = 0
    # Generate all permutations using a recursive generator
    def all_perms(seq):
        if len(seq) == 1:
            yield seq
        else:
            for i in range(len(seq)):
                for perm in all_perms(seq[:i] + seq[i+1:]):
                    yield [seq[i]] + perm

    for perm in all_perms(ways):
        a_copy = a[:]
        b_copy = b[:]
        lost = 0
        for ai, bi in perm:
            add = min(a_copy[ai], b_copy[bi])
            a_copy[ai] -= add
            b_copy[bi] -= add
            lost += add
        if lost > max_lost:
            max_lost = lost
    return max_lost

