class RPS:
    def __init__(self, first, second):
        self.first = first[:]
        self.second = second[:]

    def max_wins(self):
        sec = self.second + [self.second[0]]
        return sum(min(self.first[i], sec[i+1]) for i in range(3))

    def min_wins(self):
        first = self.first[:]
        sec = [self.second[2]] + self.second
        for i in range(3):
            if first[i] > 0:
                diff = min(first[i], sec[i])
                first[i] -= diff
                sec[i] -= diff
                if first[i] > 0:
                    diff = min(first[i], sec[i+1])
                    first[i] -= diff
                    sec[i+1] -= diff
        return sum(first)

