import sys
from collections import deque

def readline():
    return sys.stdin.readline().strip()

class Dinic:
    INF = 10**18

    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]
        self.depth = None
        self.it = None

    def add_edge(self, fr, to, cap):
        self.adj[fr].append([cap, to, len(self.adj[to])])
        self.adj[to].append([0, fr, len(self.adj[fr]) - 1])

    def bfs(self, s):
        depth = [-1] * self.n
        depth[s] = 0
        q = deque([s])
        while q:
            v = q.popleft()
            for cap, to, _ in self.adj[v]:
                if cap > 0 and depth[to] < 0:
                    depth[to] = depth[v] + 1
                    q.append(to)
        self.depth = depth

    def dfs(self, v, t, f):
        if v == t:
            return f
        for i in range(self.it[v], len(self.adj[v])):
            self.it[v] = i
            e = self.adj[v][i]
            if e[0] == 0 or self.depth[v] >= self.depth[e[1]]:
                continue
            d = self.dfs(e[1], t, min(f, e[0]))
            if d == 0:
                continue
            e[0] -= d
            self.adj[e[1]][e[2]][0] += d
            return d
        return 0

    def max_flow(self, s, t):
        flow = 0
        while True:
            self.bfs(s)
            if self.depth[t] < 0:
                return flow
            self.it = [0] * self.n
            while True:
                f = self.dfs(s, t, self.INF)
                if f == 0:
                    break
                flow += f

def main():
    N = int(readline())
    M = 3
    A = list(map(int, readline().split()))
    B = list(map(int, readline().split()))

    ans1 = 0
    for i in range(M):
        ans1 += min(A[i], B[(i + 1) % M])

    din = Dinic(2 * M + 2)
    s = 2 * M
    t = 2 * M + 1
    for i in range(M):
        din.add_edge(s, i, N)
