import sys
from collections import deque

class Edge:
    __slots__ = ('to', 'rev', 'cap')

    def __init__(self, to, rev, cap):
        self.to = to
        self.rev = rev
        self.cap = cap

class Dinic:
    INF = 10**18

    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]
        self.level = [-1] * n
        self.it = [0] * n

    def add_edge(self, fr, to, cap):
        self.g[fr].append(Edge(to, len(self.g[to]), cap))
        self.g[to].append(Edge(fr, len(self.g[fr]) - 1, 0))

    def bfs(self, s):
        level = [-1] * self.n
        level[s] = 0
        q = deque([s])
        while q:
            v = q.popleft()
            for e in self.g[v]:
                if e.cap > 0 and level[e.to] < 0:
                    level[e.to] = level[v] + 1
                    q.append(e.to)
        self.level = level

    def dfs(self, v, t, f):
        if v == t:
            return f
        for i in range(self.it[v], len(self.g[v])):
            self.it[v] = i
            e = self.g[v][i]
            if e.cap == 0 or self.level[v] >= self.level[e.to]:
                continue
            d = self.dfs(e.to, t, min(f, e.cap))
            if d == 0:
                continue
            e.cap -= d
            self.g[e.to][e.rev].cap += d
            return d
        return 0

    def flow(self, s, t):
        ans = 0
        while True:
            self.bfs(s)
            if self.level[t] < 0:
                return ans
            self.it = [0] * self.n
            while True:
                f = self.dfs(s, t, self.INF)
                if f == 0:
                    break
                ans += f

