    anc = make_path(target)

    ans = 0
    cur = 1
    right = False
    depth = h

    while cur != target:
        temp = []
        for _ in range(depth):
            temp.append(cur)
            if right:
                cur = (cur << 1) | 1
            else:
                cur = cur << 1
            right = not right

        if cur == target:
            ans += depth
            break

        temp.append(cur)
        temp.reverse()

        for i in range(1, depth + 1):
            if anc[i] == temp[i]:
                ans += ((1 << i) - 1) + depth - i + 1
                depth = i - 1
                cur = temp[i - 1]
                if cur == (temp[i] << 1):
                    cur = (temp[i] << 1) | 1
                    right = False
                else:
                    cur = temp[i] << 1
                    right = True
                break

    print(ans)

