    def build_left():
        for mask in range(1 << mid):
            s = 0
            for i in range(mid):
                if mask >> i & 1:
                    s = (s + a[i]) % m
            left.append(s)

    def build_right(idx, cur):
        if idx == n:
            right.append(cur)
            return
        build_right(idx + 1, (cur + a[idx]) % m)
