import sys

def gen(arr, k):
    if len(arr) == 1:
        return {arr[0] % k}
    mid = len(arr) // 2
    left = gen(arr[:mid], k)
    right = gen(arr[mid:], k)
    res = set(left)
    res.update(right)
    for a in left:
        for b in right:
            res.add((a + b) % k)
    return res

