@lru_cache(maxsize=None)
def solve(N, k, flag):
    if N == 1:
        if flag:
            return -1
        return 1 if k < 0 else 0

    inv = N * (N - 1) // 2

    if k < -inv - 1:
        return solve(N, -inv - 1, flag)
    if k >= inv:
        return 0

    res = 0
    for d in range(-N + 1, N):
        if flag and d > 0:
            continue
        res = (res + solve(N - 1, k - d, (d == 0) & flag) * min(N - d, d + N)) % mod
    return res

