        return (i * J + j) * K + k

    dp = [0] * size
    dp[idx(1, 0, 1)] = 1

    for i in range(1, n):
        for j in range(m + 1):
            row_start = idx(i, j, 0)
            for k in range(n + 1):
                val = dp[row_start + k]
