    # Precompute factorials up to n for faster A
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i
    def A_fast(n, k):
        return fact[n] // fact[n - k]

    z = [1]
    aaa = 0
    for i in range(2, n + 1):
        nz = [0] * (i * i // 2)
        for j, val in enumerate(z):
            if val > 0:
                for k in range(i):
                    nz[i - k - 1 + j] += val
        bbb = 0
        d = [0] * (len(z) + 1)
        for w in range(len(z) - 1, -1, -1):
            d[w] = (d[w + 1] + z[w]) % mod
        e = [0] * (len(d) + 1)
        f = [0] * (len(d) + 1)
        for w in range(len(e) - 1):
            e[w + 1] = (e[w] + d[w]) % mod
            f[w + 1] = (f[w] - w * d[w]) % mod
        for jj in range(len(z)):
            ccc = 0
            L = jj + 2
            R = min(len(z) - 1, i + jj)
            if R >= L:
                ccc = (ccc + (e[R + 1] - e[L]) * (i + 1 + jj) + (f[R + 1] - f[L])) % mod
            bbb = (bbb + ccc * z[jj]) % mod
        aaa += (bbb * A_fast(n, n - i)) % mod
        z = nz
    print(aaa % mod)

