def tf(n, M):
    C = [0] * (n+1)
    C[n] = 1
    for k in reversed(range(n)):
        C[k] = (C[k+1] * (k+1)) % M
        if not C[k]:
            break
    return C

def app(n, M):
    K = [[[1]]]
    for i in range(n-1):
        Ki = K[i]
        ni = len(Ki)
        Ki_ = [[0] * (i+2) for _ in range(ni + i + 1)]
        K.append(Ki_)
        for j, Kij in enumerate(Ki):
            for k, v in enumerate(Kij):
                for h in range(i+1):
                    Ki_[j+h][k] += v
                    Ki_[j+h][k] %= M
                Ki_[j + i + 1][i+1] += v
                Ki_[j + i + 1][i+1] %= M

    # C = comb(n, M)[n]
    C = tf(n, M)
    s = 0
