            pref[j][col] = acc
    for j in range(1, R):
        for col in range(D):
            pref[j][col] = (pref[j][col] + pref[j - 1][col]) % mod
    part = 0
    for j in range(1, R):
        for col in range(D - 1):
            part = (part + rows[j][col] * pref[j - 1][col + 1]) % mod
