def build_flat(n, mod):
    tables = [[1]]
    for i in range(n - 1):
        old = tables[i]
        old_width = i + 1
        old_rows = len(old) // old_width
        new_width = old_width + 1
        new_rows = old_rows + old_width
        new = [0] * (new_rows * new_width)
        for j in range(old_rows):
            for col in range(old_width):
                value = old[j * old_width + col]
                for off in range(old_width):
                    idx = (j + off) * new_width + col
                    new[idx] = (new[idx] + value) % mod
                idx = (j + old_width) * new_width + old_width
                new[idx] = (new[idx] + value) % mod
        tables.append(new)
    return tables

def contribution(flat, width, mod, coeff):
    R = len(flat) // width
    pref = [0] * (R * width)
    for r in range(R):
        acc = 0
        for c in range(width - 1, -1, -1):
            acc = (acc + flat[r * width + c]) % mod
            pref[r * width + c] = acc
    for r in range(1, R):
        base = r * width
        prevbase = (r - 1) * width
        for c in range(width):
            pref[base + c] = (pref[base + c] + pref[prevbase + c]) % mod
    part = 0
    for r in range(1, R):
        base = r * width
        prevbase = (r - 1) * width
        for c in range(width - 1):
            part = (part + flat[base + c] * pref[prevbase + c + 1]) % mod
    return (part * coeff) % mod

