            for d in range(1, i):
                y = x - d
                ndp1[y] = (ndp1.get(y, 0) + val * (i - d)) % mod
        dp = {k: v for k, v in ndp.items() if v}
        dp1 = {k: v for k, v in ndp1.items() if v}
