        for d in range(-i + 1, i):
            coef = i - abs(d)
            for x in range(s, e + 1):
                v = dp[i - 1][x]
                if v:
                    dp[i][x + d] = (dp[i][x + d] + v * coef) % mod
        for d in range(1, i):
            coef = i - d
            for x in range(s, e + 1):
                v = dp[i - 1][x]
                if v:
                    dp1[i][x - d] = (dp1[i][x - d] + v * coef) % mod
    return sum(dp1[-1][m + 1:]) % mod

