        if i > n:
            return sum(dp1_prev[m + 1:]) % mod
        start = m - (i - 1) * (i - 2) // 2
        end = m + (i - 1) * (i - 2) // 2
        dp_cur = [0] * L
        dp1_cur = [0] * L
        for x in range(start, end + 1):
            dp1_cur[x] = dp1_prev[x] * i % mod
        for x in range(start, end + 1):
            v = dp_prev[x]
            if v:
                for d in range(-i + 1, i):
                    dp_cur[x + d] = (dp_cur[x + d] + v * (i - abs(d))) % mod
                for d in range(1, i):
                    dp1_cur[x - d] = (dp1_cur[x - d] + v * (i - d)) % mod
        return rec(i + 1, dp_cur, dp1_cur)

    init_dp = [0] * L
    init_dp[m] = 1
    init_dp1 = [0] * L
    return rec(2, init_dp, init_dp1)

